-- Explicit lifecycle metadata and protected export requests.
create type public.archive_entity_type as enum('STUDENT','TEACHER','CLASS','SUBJECT','GROUP','GUARDIAN');
create table public.archived_entities(id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id), entity_type public.archive_entity_type not null, entity_id uuid not null, archived_by uuid not null, archived_at timestamptz not null default now(), restored_at timestamptz, unique(school_id,entity_type,entity_id), foreign key(school_id,archived_by) references public.profiles(school_id,id));
create table public.export_requests(id uuid primary key default gen_random_uuid(), school_id uuid not null references public.schools(id), requested_by uuid not null, period_start date, period_end date, scope_type text not null, scope_id uuid, datasets text[] not null, status text not null default 'PENDING' check(status in('PENDING','READY','FAILED','EXPIRED')), storage_path text, expires_at timestamptz not null default now()+interval '1 hour', created_at timestamptz not null default now(), unique(school_id,id), foreign key(school_id,requested_by) references public.profiles(school_id,id), check(period_end is null or period_start is not null and period_end>=period_start));
alter table public.archived_entities enable row level security; alter table public.archived_entities force row level security; alter table public.export_requests enable row level security; alter table public.export_requests force row level security;
create policy archives_admin on public.archived_entities for all to authenticated using(school_id=public.current_school_id() and public.is_admin()) with check(school_id=public.current_school_id() and public.is_admin()); create policy exports_admin on public.export_requests for all to authenticated using(school_id=public.current_school_id() and public.is_admin()) with check(school_id=public.current_school_id() and public.is_admin() and requested_by=public.current_profile_id());
create function public.get_delete_impact(p_entity_type public.archive_entity_type,p_entity_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare result jsonb; begin if not public.is_admin() or not exists(select 1 from public.archived_entities a where a.school_id=public.current_school_id() and a.entity_type=p_entity_type and a.entity_id=p_entity_id and a.restored_at is null) then raise exception 'archived entity not found' using errcode='42501'; end if; if p_entity_type='STUDENT' then select jsonb_build_object('memberships',(select count(*) from public.subject_group_memberships where school_id=public.current_school_id() and student_id=p_entity_id),'observations',(select count(*) from public.weekly_submission_students where school_id=public.current_school_id() and student_id=p_entity_id),'resolutions',(select count(*) from public.attendance_resolutions where school_id=public.current_school_id() and student_id=p_entity_id),'reports',(select count(*) from public.reports where school_id=public.current_school_id() and student_id=p_entity_id),'deliveries',(select count(*) from public.email_deliveries d join public.reports r on r.id=d.report_id where r.school_id=public.current_school_id() and r.student_id=p_entity_id)) into result; else result:=jsonb_build_object('entity',1); end if; return result; end $$;
revoke all on function public.get_delete_impact(public.archive_entity_type,uuid) from public; grant execute on function public.get_delete_impact(public.archive_entity_type,uuid) to authenticated;
